<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{HomeRemedy,HomeRemedyCategory,HomeRemedyIngredient,Department}; use Illuminate\Http\Request; use Illuminate\Support\Str;
class HomeRemedyAdminController extends Controller { private function data(Request $r):array{$d=$r->except(['_token','_method','ingredients']);$d['slug']=$d['slug']?:Str::slug($d['title_en']);$d['is_featured']=$r->boolean('is_featured');$d['is_published']=$r->boolean('is_published');return $d;} public function index(Request $r){$items=HomeRemedy::with('category')->when($r->q,fn($q,$v)=>$q->where('title_en','like',"%$v%")->orWhere('title_hi','like',"%$v%"))->latest()->paginate(20);return view('admin.nani-dadi.index',compact('items'));} public function create(){return view('admin.nani-dadi.form',['remedy'=>new HomeRemedy,'categories'=>HomeRemedyCategory::pluck('name_en','id'),'ingredients'=>HomeRemedyIngredient::pluck('name_en','id'),'specialities'=>Department::pluck('name_en','id')]);} public function store(Request $r){$r->validate(['title_en'=>'required','title_hi'=>'required','category_id'=>'required|exists:home_remedy_categories,id','suitable_for_en'=>'required','suitable_for_hi'=>'required','not_suitable_for_en'=>'required','not_suitable_for_hi'=>'required','red_flags_en'=>'required','red_flags_hi'=>'required','when_to_see_doctor_en'=>'required','when_to_see_doctor_hi'=>'required']);$x=HomeRemedy::create($this->data($r));$x->ingredients()->sync($r->input('ingredients',[]));return redirect()->route('admin.nani-dadi.index')->with('success','Remedy created.');} public function edit(HomeRemedy $remedy){return view('admin.nani-dadi.form',['remedy'=>$remedy,'categories'=>HomeRemedyCategory::pluck('name_en','id'),'ingredients'=>HomeRemedyIngredient::pluck('name_en','id'),'specialities'=>Department::pluck('name_en','id')]);} public function update(Request $r,HomeRemedy $remedy){$r->validate(['title_en'=>'required','title_hi'=>'required','category_id'=>'required|exists:home_remedy_categories,id']);$remedy->update($this->data($r));$remedy->ingredients()->sync($r->input('ingredients',[]));return back()->with('success','Remedy updated.');} public function destroy(HomeRemedy $remedy){$remedy->delete();return back()->with('success','Remedy deleted.');} public function toggle(HomeRemedy $remedy){$remedy->update(['is_published'=>!$remedy->is_published,'medical_review_status'=>!$remedy->is_published?'published':'draft']);return back()->with('success','Publication status updated.');} }
